import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.StringTokenizer;
import java.util.Arrays;
import java.util.Comparator;

public class Main {

    static class Line {
        long y1, y2;

        Line(long y1, long y2) {
            this.y1 = y1;
            this.y2 = y2;
        }
    }

    static class FenwickTree {
        int size;
        int[] tree;

        FenwickTree(int size) {
            this.size = size;
            this.tree = new int[size + 1];
        }

        void add(int i, int delta) {
            for (; i <= size; i += i & -i) {
                tree[i] += delta;
            }
        }

        int query(int i) {
            int sum = 0;
            for (; i > 0; i -= i & -i) {
                sum += tree[i];
            }
            return sum;
        }
    }

    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }
    }

    public static void main(String[] args) {
        FastReader in = new FastReader();
        String tokenN = in.next();
        if (tokenN == null) return;

        int n = Integer.parseInt(tokenN);
        long x1 = in.nextLong();
        long x2 = in.nextLong();

        Line[] lines = new Line[n];
        for (int i = 0; i < n; i++) {
            long a = in.nextLong();
            long b = in.nextLong();
            lines[i] = new Line(a * x1 + b, a * x2 + b);
        }

        // Caso especial: X1 == X2
        if (x1 == x2) {
            Arrays.sort(lines, Comparator.comparingLong(l -> l.y1));
            long ans = 0;
            int count = 1;
            for (int i = 1; i < n; i++) {
                if (lines[i].y1 == lines[i - 1].y1) {
                    count++;
                } else {
                    ans += (long) count * (count - 1) / 2;
                    count = 1;
                }
            }
            ans += (long) count * (count - 1) / 2;
            System.out.println(ans);
            return;
        }

        // Ordenar por Y1 crescente, desempate por Y2 decrescente
        Arrays.sort(lines, (l1, l2) -> {
            if (l1.y1 != l2.y1) {
                return Long.compare(l1.y1, l2.y1);
            }
            return Long.compare(l2.y2, l1.y2);
        });

        // Coleta e compressão de coordenadas para Y2
        long[] uniqueY2 = new long[n];
        for (int i = 0; i < n; i++) {
            uniqueY2[i] = lines[i].y2;
        }
        Arrays.sort(uniqueY2);
        int m = 0;
        for (int i = 0; i < n; i++) {
            if (i == 0 || uniqueY2[i] != uniqueY2[i - 1]) {
                uniqueY2[m++] = uniqueY2[i];
            }
        }

        // Fenwick Tree para contar pares concordantes
        FenwickTree bit = new FenwickTree(m);
        long concordantPairs = 0;

        for (int i = 0; i < n; i++) {
            int rank = Arrays.binarySearch(uniqueY2, 0, m, lines[i].y2) + 1;
            concordantPairs += bit.query(rank - 1);
            bit.add(rank, 1);
        }

        long totalPairs = (long) n * (n - 1) / 2;
        long ans = totalPairs - concordantPairs;

        System.out.println(ans);
    }
}
